"""Release SBOM completeness checks (tools/rf_release_sbom.py), standard library only."""
from __future__ import annotations

import copy
import importlib.util
import json
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
_spec = importlib.util.spec_from_file_location('rf_release_sbom', ROOT / 'tools' / 'rf_release_sbom.py')
sbom = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(sbom)

H1 = 'a' * 64
H2 = 'b' * 64
H3 = 'c' * 64
LOCK = (
    '# This file was autogenerated by uv via the following command:\n'
    '#    uv pip compile x.in --universal --generate-hashes -o x.txt\n'
    'Typing_Extensions==4.16.0 \\\n'
    f'    --hash=sha256:{H1} \\\n'
    f'    --hash=sha256:{H2}\n'
    '    # via pydantic\n'
    "colorama==0.4.6 ; sys_platform == 'win32' \\\n"
    f'    --hash=sha256:{H3}\n'
)


def _bom():
    return {
        'bomFormat': 'CycloneDX',
        'specVersion': '1.6',
        'serialNumber': 'urn:uuid:d2da9295-6bc5-5eb9-a41e-0c7cc9867ebe',
        'metadata': {'component': {'name': 'RightsFrames-Termux', 'version': '0.3.0'}},
        'components': [
            {
                'name': 'typing-extensions', 'version': '4.16.0',
                'purl': 'pkg:pypi/typing-extensions@4.16.0',
                'externalReferences': [{'type': 'distribution', 'hashes': [
                    {'alg': 'SHA-256', 'content': H1}, {'alg': 'SHA-256', 'content': H2}]}],
            },
            {
                'name': 'colorama', 'version': '0.4.6',
                'purl': 'pkg:pypi/colorama@0.4.6',
                'externalReferences': [{'type': 'distribution', 'hashes': [
                    {'alg': 'SHA-256', 'content': H3}]}],
            },
        ],
    }


def test_parse_lock_reads_versions_hashes_and_markers():
    lock = sbom.parse_lock(LOCK)
    assert lock == {
        'typing-extensions': ('4.16.0', frozenset({H1, H2})),
        'colorama': ('0.4.6', frozenset({H3})),
    }


def test_parse_lock_rejects_unhashed_and_unpinned_lines():
    with pytest.raises(sbom.SBOMError):
        sbom.parse_lock('fastapi==0.1\n')
    with pytest.raises(sbom.SBOMError):
        sbom.parse_lock(f'fastapi>=0.1 --hash=sha256:{H1}\n')
    with pytest.raises(sbom.SBOMError):
        sbom.parse_lock('# only comments\n')


def test_runtime_lock_is_fully_hashed():
    lock = sbom.parse_lock((ROOT / 'core' / 'requirements.txt').read_text(encoding='utf-8'))
    for direct in ('cryptography', 'fastapi', 'pydantic', 'starlette', 'uvicorn'):
        assert direct in lock
    assert all(hashes for _, hashes in lock.values())


def test_complete_sbom_passes():
    assert sbom.verify_sbom(_bom(), sbom.parse_lock(LOCK), '0.3.0') == 2


@pytest.mark.parametrize('tamper, message', [
    (lambda b: b['components'].pop(), 'missing from SBOM'),
    (lambda b: b['components'].append({'name': 'evil', 'version': '1', 'purl': 'pkg:pypi/evil@1'}),
     'not in the lock file'),
    (lambda b: b['components'].append(copy.deepcopy(b['components'][0])), 'listed twice'),
    (lambda b: b['components'][0].update(version='4.15.0', purl='pkg:pypi/typing-extensions@4.15.0'),
     'lock version'),
    (lambda b: b['components'][1]['externalReferences'][0]['hashes'][0].update(content=H1),
     'hashes differ'),
    (lambda b: b['components'][1].update(purl='pkg:pypi/other@0.4.6'), 'purl'),
    (lambda b: b['metadata']['component'].update(version='9.9.9'), 'root version'),
    (lambda b: b['metadata']['component'].update(name='Other'), 'root component'),
    (lambda b: b.update(serialNumber='1234'), 'serialNumber'),
    (lambda b: b.update(specVersion='1.4'), 'specVersion'),
    (lambda b: b.update(bomFormat='SPDX'), 'CycloneDX'),
])
def test_tampered_sbom_is_rejected(tamper, message):
    bom = _bom()
    tamper(bom)
    with pytest.raises(sbom.SBOMError, match=message):
        sbom.verify_sbom(bom, sbom.parse_lock(LOCK), '0.3.0')


def test_verify_cli(tmp_path, capsys):
    (tmp_path / 'lock.txt').write_text(LOCK, encoding='utf-8')
    (tmp_path / 'bom.json').write_text(json.dumps(_bom()), encoding='utf-8')
    assert sbom.main(['verify', '--sbom', str(tmp_path / 'bom.json'),
                      '--requirements', str(tmp_path / 'lock.txt'), '--version', '0.3.0']) == 0
    assert 'SBOM_VERIFICATION=PASS components=2' in capsys.readouterr().out
    assert sbom.main(['verify', '--sbom', str(tmp_path / 'bom.json'),
                      '--requirements', str(tmp_path / 'lock.txt'), '--version', '1.0.0']) == 1
    assert 'SBOM_VERIFICATION=FAIL' in capsys.readouterr().out


def test_generate_rejects_bad_identity(tmp_path):
    (tmp_path / 'lock.txt').write_text(LOCK, encoding='utf-8')
    with pytest.raises(sbom.SBOMError, match='commit'):
        sbom.generate(tmp_path / 'lock.txt', '0.3.0', 'o/r', 'HEAD', 'v0.3.0', 0)
    with pytest.raises(sbom.SBOMError, match='repository'):
        sbom.generate(tmp_path / 'lock.txt', '0.3.0', 'bad repo', 'a' * 40, 'v0.3.0', 0)
